"""Independent Telegram Desktop compatible views of signed account observations.

The source remains data/*.jsonl. Telegram does not generate or sign these views.
Messages are streamed in ascending ID order through a disk-backed index.
"""
from datetime import datetime, timezone
from html import escape
from itertools import islice
import json
import re
import sqlite3

from .store import canonical

NOTE = ("Generated by TgWitness from selected Telegram API observations. Dates use UTC. "
        "This is a Telegram Desktop compatible view, not an export generated by Telegram Desktop. "
        "See manifest.json for coverage, data/*.jsonl for source records, and hashes/index.jsonl for file hash ranges.")
MEDIA_PATH = re.compile(r"media/[a-f0-9]{64}\Z")
ENTITIES = {"Bold": "bold", "Italic": "italic", "Code": "code", "Pre": "pre", "Underline": "underline",
            "Strike": "strikethrough", "Spoiler": "spoiler", "Blockquote": "blockquote", "Url": "link",
            "TextUrl": "text_link", "Mention": "mention", "MentionName": "mention_name", "Hashtag": "hashtag",
            "Cashtag": "cashtag", "BotCommand": "bot_command", "Email": "email", "Phone": "phone",
            "CustomEmoji": "custom_emoji"}


def peer(value):
    if not isinstance(value, int) or not value:
        return None
    return ("channel", -value - 1000000000000) if value < -1000000000000 else ("chat", -value) if value < 0 else ("user", value)


def peer_id(value):
    identity = peer(value)
    return f"{identity[0]}{identity[1]}" if identity else None


def name(value):
    value = value or {}
    return value.get("title") or " ".join(value.get(k) or "" for k in ("first_name", "last_name")).strip() or None


def dates(value, key="date"):
    if not value:
        return {}
    at = datetime.fromisoformat(value.replace("Z", "+00:00"))
    at = at.replace(tzinfo=at.tzinfo or timezone.utc).astimezone(timezone.utc)
    return {key: at.strftime("%Y-%m-%dT%H:%M:%S"), key + "_unixtime": str(int(at.timestamp()))}


def rich_text(text, entities):
    # MTProto offsets count UTF-16 code units, including both halves of emoji.
    boundaries, units = {0: 0}, 0
    for index, char in enumerate(text, 1):
        units += 2 if ord(char) > 0xFFFF else 1
        boundaries[units] = index
    spans = []
    for item in entities or []:
        start, length = item.get("offset"), item.get("length")
        kind = ENTITIES.get(str(item.get("_", "")).removeprefix("MessageEntity"))
        if (type(start) is not int or type(length) is not int or length <= 0 or not kind
                or start not in boundaries or start + length not in boundaries):
            continue
        value = {"type": kind}
        for source, target in (("url", "href"), ("language", "language"), ("user_id", "user_id"),
                               ("document_id", "document_id")):
            if source in item:
                value[target] = item[source]
        spans.append((boundaries[start], boundaries[start + length], value))
    pieces, cursor = [], 0
    for start, end, value in sorted(spans, key=lambda s: (s[0], -s[1])):
        if start < cursor:
            continue  # Nested source entities remain available in signed JSONL.
        if start > cursor:
            pieces.append({"type": "plain", "text": text[cursor:start]})
        pieces.append({**value, "text": text[start:end]})
        cursor = end
    if cursor < len(text) or not pieces:
        pieces.append({"type": "plain", "text": text[cursor:]})
    mixed = [p["text"] if p["type"] == "plain" else p for p in pieces]
    return (text if all(p["type"] == "plain" for p in pieces) else mixed), pieces


def message(row):
    action = row.get("action") or {}
    result = {"id": row["id"], "type": "service" if action else "message", **dates(row.get("date")),
              **dates(row.get("edit_date"), "edited")}
    sender = peer_id(row.get("from_id"))
    if sender:
        label = "actor" if action else "from"
        result.update({label: name(row.get("sender")), label + "_id": sender})
    reply = row.get("reply_to") or {}
    if reply.get("reply_to_msg_id"):
        result["reply_to_message_id"] = reply["reply_to_msg_id"]
    result["text"], result["text_entities"] = rich_text(row.get("text") or "", row.get("entities"))
    if action:
        actions = {"MessageActionChatCreate": "create_group", "MessageActionChatEditTitle": "edit_group_title",
            "MessageActionChatEditPhoto": "edit_group_photo", "MessageActionChatDeletePhoto": "delete_group_photo",
            "MessageActionChatAddUser": "invite_members", "MessageActionChatDeleteUser": "remove_members",
            "MessageActionChatJoinedByLink": "join_group_by_link", "MessageActionPinMessage": "pin_message",
            "MessageActionHistoryClear": "clear_history", "MessageActionChannelCreate": "create_channel"}
        result["action"] = actions.get(action.get("_"), "unsupported")
        if action.get("title"):
            result["title"] = action["title"]
    forward = row.get("fwd_from") or {}
    if forward.get("from_name"):
        result["forwarded_from"] = forward["from_name"]
    if row.get("post_author"):
        result["author"] = row["post_author"]
    media = row.get("media") or {}
    document = media.get("document") or {}
    if document.get("mime_type"):
        result["mime_type"] = document["mime_type"]
    for attribute in document.get("attributes", []):
        for source, target in (("file_name", "file_name"), ("duration", "duration_seconds"), ("w", "width"), ("h", "height")):
            if source in attribute:
                result[target] = attribute[source]
    attachments = row.get("attachments") or []
    if attachments:
        attachment = attachments[0]
        field = "photo" if attachment["kind"] == "photo" else "file"
        path = attachment.get("file")
        result[field] = path if isinstance(path, str) and MEDIA_PATH.fullmatch(path) else (
            "(File not included. See tgwitness_media and the signed acquisition records.)")
        if attachment.get("expected_bytes") is not None:
            result[field + "_size"] = attachment["expected_bytes"]
        kind = {"video": "video_file", "audio": "audio_file", "voice": "voice_message",
                "video_message": "video_message", "sticker": "sticker", "animation": "animation"}.get(attachment["kind"])
        if kind:
            result["media_type"] = kind
        result["tgwitness_media"] = attachments
    if media.get("geo"):
        geo = media["geo"]
        result["location_information"] = {"latitude": geo.get("lat"), "longitude": geo.get("long")}
    if media.get("phone_number"):
        result["contact_information"] = {k: media.get(k) for k in ("first_name", "last_name", "phone_number")}
    if media.get("poll"):
        poll = media["poll"]
        question = poll.get("question") or ""
        result["poll"] = {"question": question.get("text", "") if isinstance(question, dict) else question,
                          "closed": bool(poll.get("closed")), "total_voters": (media.get("results") or {}).get("total_voters")}
    return result


class DesktopExport:
    def __init__(self, directory, inventory, receipts, job, coverage):
        self.directory, self.inventory, self.receipts, self.job, self.coverage = directory, inventory, receipts, job, coverage
        # SQLite temporary databases are disk-backed and removed when closed.
        self.index = sqlite3.connect("")
        try:
            self.index_messages()
        except BaseException:
            self.index.close()
            raise

    def index_messages(self):
        self.index.execute("CREATE TABLE messages (chat INTEGER, id INTEGER, path TEXT, offset INTEGER, bytes INTEGER, PRIMARY KEY(chat,id))")
        for envelope in self.receipts:
            receipt = envelope["statement"]
            if receipt["category"] != "messages":
                continue
            with (self.directory / receipt["data_file"]).open("rb") as stream:
                while True:
                    offset, raw = stream.tell(), stream.readline()
                    if not raw:
                        break
                    row = json.loads(raw)
                    self.index.execute("INSERT INTO messages VALUES (?,?,?,?,?)", (row["chat_id"], row["id"], receipt["data_file"], offset, len(raw)))
        self.index.commit()

    def close(self):
        self.index.close()

    def rows(self, chat_id):
        stream, opened = None, None
        try:
            for path, offset in self.index.execute("SELECT path,offset FROM messages WHERE chat=? ORDER BY id", (chat_id,)):
                if path != opened:
                    if stream:
                        stream.close()
                    stream, opened = (self.directory / path).open("rb"), path
                stream.seek(offset)
                yield json.loads(stream.readline())
        finally:
            if stream:
                stream.close()

    def metadata(self, category):
        for envelope in self.receipts:
            receipt = envelope["statement"]
            if receipt["category"] == category:
                with (self.directory / receipt["data_file"]).open("rb") as stream:
                    for raw in stream:
                        yield json.loads(raw)

    def chat(self, chat):
        kind = {"private": "personal_chat", "bot": "bot_chat", "group": "private_group",
                "supergroup": "private_supergroup", "channel": "private_channel"}[chat["kind"]]
        if chat["id"] == self.job["account_id"]:
            kind = "saved_messages"
        elif chat.get("username") and chat["kind"] in ("supergroup", "channel"):
            kind = "public_" + chat["kind"]
        return {"name": chat.get("title"), "type": kind, "id": peer(chat["id"])[1]}

    def json(self):
        yield b'{"about":' + canonical(NOTE)
        for row in self.metadata("profile"):
            if row.get("type") == "profile_music":
                continue
            data = row.get("data") or {}
            user = next((u for u in data.get("users", []) if u.get("id") == self.job["account_id"]), {})
            profile = {"user_id": self.job["account_id"], "first_name": user.get("first_name") or "",
                       "last_name": user.get("last_name") or "", "phone_number": user.get("phone") or "",
                       "username": ("@" + user["username"]) if user.get("username") else "",
                       "bio": (data.get("full_user") or {}).get("about") or ""}
            yield b',"personal_information":' + canonical(profile)
            break
        if self.job["options"].get("include_contacts"):
            yield b',"contacts":{"about":"Selected contacts visible to this account.","list":['
            comma = b""
            for row in self.metadata("contacts"):
                value = row.get("data") or {}
                yield comma + canonical({"first_name": value.get("first_name") or "", "last_name": value.get("last_name") or "",
                                         "phone_number": value.get("phone") or "", **dates(value.get("date"))})
                comma = b"," 
            yield b"]}"
        for key, category in (("sessions", "sessions"), ("web_sessions", "sessions"),
                              ("profile_pictures", "profile_photos"), ("stories", "stories")):
            if not any(e["statement"]["category"] == category for e in self.receipts):
                continue
            sessions = category == "sessions"
            yield b"," + canonical(key) + (b':{"about":"Selected session metadata.","list":[' if sessions else b":[")
            comma = b""
            for row in self.metadata(category):
                value = row.get("data") or {}
                if sessions:
                    if row.get("type") != ("web" if key == "web_sessions" else "telegram"):
                        continue
                    translated = {**dates(value.get("date_active"), "last_active"), **dates(value.get("date_created"), "created")}
                    fields = {"ip": "last_ip", "country": "last_country", "region": "last_region", "app_name": "application_name",
                        "app_version": "application_version", "device_model": "device_model", "platform": "platform",
                        "system_version": "system_version", "domain": "domain_name", "browser": "browser"}
                    translated.update({target: value[source] for source, target in fields.items() if source in value})
                else:
                    attachments = row.get("attachments", [])
                    path = attachments[0].get("file") if attachments else None
                    translated = {**dates(value.get("date")), "photo" if category == "profile_photos" else "media":
                        path if isinstance(path, str) and MEDIA_PATH.fullmatch(path) else "(File not included; see signed acquisition records.)",
                        "tgwitness_media": attachments}
                    if category == "stories":
                        translated.update(dates(value.get("expire_date"), "expires"), pinned=bool(value.get("pinned")))
                yield comma + canonical(translated)
                comma = b"," 
            yield b"]}" if sessions else b"]"
        for group, left in (("chats", False), ("left_chats", True)):
            yield b"," + canonical(group) + b':{"about":"Selected visible chat history.","list":['
            comma = b""
            for chat in self.inventory["chats"]:
                if not chat["selected"] or bool(chat.get("left")) != left:
                    continue
                yield comma + canonical(self.chat(chat))[:-1] + b',"messages":['
                message_comma = b""
                for row in self.rows(chat["id"]):
                    yield message_comma + canonical(message(row))
                    message_comma = b"," 
                yield b"]}"
                comma = b"," 
            yield b"]}"
        yield b',"tgwitness":' + canonical({"job_id": self.job["job_id"], "options": self.job["options"],
            "coverage": self.coverage, "source": "data/*.jsonl", "file_hashes": "hashes/index.jsonl"}) + b"}\n"

    @staticmethod
    def head(title):
        return ('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width">'
            '<title>' + escape(title) + '</title><style>body{font:16px/1.6 system-ui;margin:2rem auto;padding:0 1rem;max-width:850px;'
            'color:#17212b;background:#eef2f5}article{background:white;border-radius:12px;padding:1rem;margin:1rem 0}'
            'pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}small{color:#526575}a{color:#1263a1}'
            'li{margin:.5rem 0}nav{display:flex;gap:2rem}</style><main><h1>' + escape(title) + '</h1>').encode()

    def html(self):
        selected = [c for c in self.inventory["chats"] if c["selected"]]

        def index():
            yield self.head("Exported Telegram data")
            yield ("<p>" + escape(NOTE) + '</p><p><a href="index.html">Acquisition details and coverage</a></p><ul>').encode()
            for number, chat in enumerate(selected, 1):
                yield (f'<li><a href="chats/chat_{number:03d}/messages.html">' + escape(chat.get("title") or str(chat["id"])) + "</a></li>").encode()
            yield b"</ul></main></html>"
        yield "export_results.html", index()
        for number, chat in enumerate(selected, 1):
            plan, size, count = [], 0, 0
            for (length,) in self.index.execute("SELECT bytes FROM messages WHERE chat=? ORDER BY id", (chat["id"],)):
                if count and (count >= 500 or size + length > 512 * 1024):
                    plan.append(count)
                    size, count = 0, 0
                size += length
                count += 1
            if count or not plan:
                plan.append(count)
            pages = len(plan)
            rows = iter(self.rows(chat["id"]))
            try:
                for page, count in enumerate(plan, 1):
                    batch = list(islice(rows, count))
                    filename = lambda n: "messages" + (str(n) if n > 1 else "") + ".html"

                    def content(batch=batch, chat=chat, page=page, pages=pages):
                        yield self.head(chat.get("title") or str(chat["id"]))
                        yield b'<nav><a href="../../export_results.html">All chats</a>'
                        if page > 1:
                            yield f'<a href="{filename(page - 1)}">Previous</a>'.encode()
                        if page < pages:
                            yield f'<a href="{filename(page + 1)}">Next</a>'.encode()
                        yield b"</nav>"
                        for row in batch:
                            value = message(row)
                            yield (f'<article id="message{row["id"]}"><strong>' + escape(name(row.get("sender")) or str(row.get("from_id") or ""))
                                + "</strong> <small>" + escape(value.get("date", "")) + ' UTC</small><pre>'
                                + escape(row.get("text") or "") + "</pre>").encode()
                            for attachment in row.get("attachments", []):
                                path = attachment.get("file")
                                if isinstance(path, str) and MEDIA_PATH.fullmatch(path):
                                    yield f'<p><a href="../../{path}">Saved {escape(attachment["kind"])}</a></p>'.encode()
                                    if attachment["kind"] == "photo":
                                        yield f'<img src="../../{path}" alt="Photo" loading="lazy" style="max-width:100%;height:auto">'.encode()
                                else:
                                    yield ("<p>" + escape(attachment.get("outcome", "unavailable")) + ": "
                                        + escape(attachment.get("reason", "")) + "</p>").encode()
                            yield b"</article>"
                        yield b"</main></html>"
                    yield f"chats/chat_{number:03d}/{filename(page)}", content()
            finally:
                rows.close()
